enum BrushRenderType {
  solidRound,
  fuzzyRound,
  solidSquare,
  fuzzySquare,
  seeThru,
  patternStamp,
}

class TuxBrush {
  const TuxBrush({
    required this.id,
    required this.assetPath,
    required this.name,
    required this.renderType,
    required this.spacingRatio,
    required this.frames,
    required this.rotates,
    required this.directional,
  });

  final String id;
  final String assetPath;
  final String name;
  final BrushRenderType renderType;
  final double spacingRatio;
  final int frames;
  final bool rotates;
  final bool directional;
}

class TuxStamp {
  const TuxStamp({required this.category, required this.assetPath, required this.name});
  final String category;
  final String assetPath;
  final String name;
}

