  static TuxBrush findBrush(String? assetPath) {
    if (assetPath == null) return brushes[3]; // default aa_round_24
    for (final b in brushes) {
      if (b.assetPath == assetPath || b.id == assetPath) return b;
    }
    return brushes[3];
  }

